from itertools import product

def check_kawaii(sequence):
    L = len(sequence)

    def get_first_last(k):
        indices = [i for i, x in enumerate(sequence) if x == k]
        if not indices:
            return None, None
        return indices[0], indices[-1]

    # Check k=2
    k = 2
    if k in sequence:
        # Condition 1: k-1 must appear
        if (k - 1) not in sequence:
            return False

        # Condition 2: First(k-1) < Last(k)
        f_km1, _ = get_first_last(k - 1)
        _, lk = get_first_last(k)
        if f_km1 >= lk:
            return False

    # Check k=3
    k = 3
    if k in sequence:
        # Condition 1: k-1 must appear
        if (k - 1) not in sequence:
            return False

        # Condition 2: First(k-1) < Last(k)
        f_km1, _ = get_first_last(k - 1)
        _, lk = get_first_last(k)
        if f_km1 >= lk:
            return False

    return True

count = 0
# All sequences are drawn from {1, 2, 3}
for seq in product([1, 2, 3], repeat=3):
    if check_kawaii(seq):
        count += 1
        # print(seq) # Optional: print valid sequences

print(count)
